using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Terminal fields Mutagen kept as raw bytes get xEdit's names and types, as Furniture already has them:
// PNAM Default Primitive Color, FNAM flags (U16), JNAM/GNAM activation angles (U16) and the FNPR marker entry points.
// Each test reads a whole terminal from Starfield.esm (minus its FULL, a localized string ID this unlocalized test
// reader would read as text) with both readers and writes it back byte for byte.
public class TerminalFieldTests
{
    private static IEnumerable<ITerminalGetter> Read(string hex)
        => ReadBoth<ITerminalGetter>(Record("TERM", Hex(hex)), f => Terminal.CreateFromBinary(f), (s, p) => TerminalBinaryOverlay.TerminalFactory(s, p));

    private static void WritesBack(ITerminalGetter term, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => term.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // CY_GlenHurst_CondoTerminal (203BB8:Starfield.esm), the only terminal with an FNPR
    private const string Condo = "";

    // LC017_RobotTurretControl (0029A4:Starfield.esm), FNAM 02 00 (Ignored By Sandbox)
    private const string Turret = "";

    [Fact]
    public void Condo_AnglesColorAndEntryPoints()
    {
        foreach (var term in Read(Condo))
        {
            term.Flags.ShouldBe((Terminal.Flag)0);
            term.ActivationAngleForPlayer.ShouldBe((ushort)360);
            term.ActivationAngleForSittingActor.ShouldBe((ushort)360);
            var color = term.DefaultPrimitiveColor!.Value;
            color.R.ShouldBe((byte)0xCC);
            color.G.ShouldBe((byte)0x4C);
            color.B.ShouldBe((byte)0x33);
            var entry = term.MarkerEntryPoints!.Single();
            entry.Type.ShouldBe(Furniture.AnimationType.Sit);
            entry.EntryPoints.ShouldBe(Furniture.EntryPointType.Front | Furniture.EntryPointType.Right | Furniture.EntryPointType.Left);
            WritesBack(term, Condo);
        }
    }

    [Fact]
    public void Turret_IgnoredBySandbox()
    {
        foreach (var term in Read(Turret))
        {
            term.Flags.ShouldBe(Terminal.Flag.IgnoredBySandbox);
            term.ActivationAngleForPlayer.ShouldBe((ushort)360);
            (term.MarkerEntryPoints ?? []).ShouldBeEmpty();
            WritesBack(term, Turret);
        }
    }
}
